        "jsCode": "// Format conversation history for AI\nconst history = $input.all();\nconst contextData = $('Build Context').item.json;\n\nconst messages = [];\nlet latestVersion = 0;\nlet originalRequirements = '';\n\n// Process all messages\nfor (const item of history) {\n  const fields = item.json.fields;\n  \n  // Track latest version\n  if (fields.design_version > latestVersion) {\n    latestVersion = fields.design_version;\n  }\n  \n  // Capture original requirements\n  if (fields.type === 'pm' && fields.requirements) {\n    originalRequirements = fields.requirements;\n  }\n  \n  // Build message for AI context\n  let content = fields.content;\n  \n  // For AI responses, include snippet of HTML generated\n  if (fields.type === 'ai' && fields.html_output) {\n    content += `\\n\\n[Generated HTML v${fields.design_version}]: ${fields.html_output.substring(0, 300)}...`;\n  }\n  \n  messages.push({\n    role: fields.role,\n    content: content,\n    type: fields.type,\n    version: fields.design_version\n  });\n}\n\n// Build context summary\nconst contextSummary = `\n=== CONVERSATION CONTEXT ===\nChat ID: ${contextData.chatId}\nOriginal Requirements: ${originalRequirements || 'N/A'}\nCurrent Version: ${latestVersion}\nTotal Messages: ${messages.length}\n\n=== CONVERSATION HISTORY ===\n${messages.map((m, i) => `[${i + 1}] ${m.type.toUpperCase()} (v${m.version}): ${m.content}`).join('\\n\\n')}\n\n=== NEW REQUEST ===\n${contextData.inputType === 'chat' ? 'User: ' + contextData.userMessage : 'PM Requirements: ' + contextData.requirements}\n`;\n\nreturn {\n  json: {\n    messages: messages,\n    contextSummary: contextSummary,\n    latestVersion: latestVersion,\n    newVersion: latestVersion + 1,\n    originalRequirements: originalRequirements,\n    chatId: contextData.chatId,\n    inputType: contextData.inputType,\n    userMessage: contextData.userMessage,\n    requirements: contextData.requirements\n  }\n};"
